package com.ahdre.pip;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import java.io.*;import org.json.*;

class V12Features {
 final PetService s;Decor home,ball;WindowManager.LayoutParams hp,bp;int mode=0,accessory=0,reminder=45;boolean homeVisible=true,goHome=false,dragBall=false;float companyX,companyY;long nextReminder;int phase=0,catches=0,returns=0;boolean ballVisible=false;double bx,by,vx,vy,gameAge;float[][] ax=new float[11][8],ay=new float[11][8];
 V12Features(PetService service){s=service;loadAnchors();home=new Decor(false);ball=new Decor(true);hp=params(s.dp(56),s.dp(48));bp=params(s.dp(20),s.dp(20));reload(true);s.wm.addView(home,hp);s.wm.addView(ball,bp);ball.setVisibility(View.INVISIBLE);if(!homeVisible)home.setVisibility(View.INVISIBLE);companyX=s.lp.x;companyY=s.lp.y;}
 WindowManager.LayoutParams params(int w,int h){WindowManager.LayoutParams p=new WindowManager.LayoutParams(w,h,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;return p;}
 void loadAnchors(){try(InputStream in=s.getAssets().open("accessory-anchors.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[2048];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);JSONArray poses=new JSONObject(out.toString("UTF-8")).getJSONArray("poses");for(int i=0;i<poses.length();i++){JSONObject p=poses.getJSONObject(i);ax[p.getInt("row")][p.getInt("frame")]=(float)p.getDouble("x");ay[p.getInt("row")][p.getInt("frame")]=(float)p.getDouble("y");}}catch(Exception e){android.util.Log.e("Pip","Accessory anchor load failed",e);}}
 void reload(boolean moveHome){int oldReminder=reminder,oldMode=mode;mode=s.prefs.getInt("mode",0);accessory=s.prefs.getInt("accessory",0);reminder=s.prefs.getInt("reminderMinutes",45);homeVisible=s.prefs.getBoolean("homeVisible",true);if(nextReminder==0||oldReminder!=reminder)nextReminder=SystemClock.uptimeMillis()+Math.max(1,reminder)*60000L;if(hp!=null&&moveHome){hp.x=Math.round(s.prefs.getFloat("homeX",.85f)*Math.max(0,s.width-hp.width));hp.y=Math.round(s.prefs.getFloat("homeY",1)*Math.max(0,s.height-hp.height-s.dp(32)));clampHome();}if(moveHome||oldMode!=mode){companyX=s.lp.x;companyY=s.lp.y;}if(s.pet!=null){s.drawnRow=-1;s.pet.invalidate();}if(home!=null&&home.isAttachedToWindow()){s.wm.updateViewLayout(home,hp);home.invalidate();}}
 void clampHome(){hp.x=Math.max(0,Math.min(s.width-hp.width,hp.x));hp.y=Math.max(s.dp(28),Math.min(s.height-hp.height-s.dp(32),hp.y));}
 void saveHome(){s.prefs.edit().putFloat("homeX",hp.x/(float)Math.max(1,s.width-hp.width)).putFloat("homeY",hp.y/(float)Math.max(1,s.height-hp.height-s.dp(32))).apply();}
 void visible(boolean visible){if(home!=null)home.setVisibility(visible&&homeVisible?View.VISIBLE:View.INVISIBLE);if(ball!=null)ball.setVisibility(visible&&ballVisible?View.VISIBLE:View.INVISIBLE);}
 void action(String action){if("BALL".equals(action)){s.touch();s.happyUntil=0;s.playUntil=0;throwBall(s.lp.x+s.lp.width/2,s.lp.y+s.lp.height/2,s.random.nextBoolean()?s.dp(140):-s.dp(140),-s.dp(110));}else if("HIDE_BALL".equals(action)){phase=0;ballVisible=false;ball.setVisibility(View.INVISIBLE);}else if("HOME".equals(action)){s.touch();goHome=true;}else if("REMIND".equals(action))remind();else if("SNAPSHOT".equals(action)){s.savePosition();}else if("IMPORT".equals(action)){s.touch();s.happyUntil=0;s.playUntil=0;s.sizeDp=s.prefs.getInt("size",104);s.lp.width=s.dp(s.sizeDp);s.lp.height=s.lp.width*208/192;reload(true);phase=0;ballVisible=false;goHome=false;s.lp.x=Math.round(s.prefs.getFloat("posX",.9f)*Math.max(0,s.width-s.lp.width));s.lp.y=Math.round(s.prefs.getFloat("posY",.9f)*Math.max(0,s.height-s.lp.height));s.clamp();companyX=s.lp.x;companyY=s.lp.y;s.update();}else if("CONFIG".equals(action))reload(false);}
 void throwBall(double x,double y,double dx,double dy){bx=x;by=y;vx=Math.max(-s.dp(350),Math.min(s.dp(350),dx));vy=Math.max(-s.dp(260),Math.min(s.dp(80),dy));phase=1;ballVisible=true;gameAge=0;ball.setVisibility(View.VISIBLE);updateBall();}
 static double move(double value,double target,double max){return value+Math.max(-max,Math.min(max,target-value));}
 boolean tick(int dt,long now){
  visible(true);if(reminder>0&&now>=nextReminder){remind();nextReminder=now+reminder*60000L;}
  double floor=hp.y+hp.height,homeCenter=Math.max(s.lp.width/2,Math.min(s.width-s.lp.width/2,hp.x-s.lp.width*.2)),pace=s.dp(s.speed*2.4f+20)*dt/1000.0;
  if(phase>0&&!dragBall){gameAge+=dt/1000.0;
   if(phase==1){bx+=vx*dt/1000;by+=vy*dt/1000;vy+=s.dp(240)*dt/1000.0;vx*=Math.pow(.55,dt/1000.0);if(bx<0){bx=0;vx=Math.abs(vx)*.6;}if(bx>s.width-bp.width){bx=s.width-bp.width;vx=-Math.abs(vx)*.6;}if(by>floor-bp.height){by=floor-bp.height;vy=-Math.abs(vy)*.42;if(Math.abs(vy)<s.dp(15))vy=0;}if(gameAge>18){vx=0;by=floor-bp.height;}double target=bx+bp.width/2-s.lp.width/2;s.direction=target>=s.lp.x?1:-1;s.lp.x=(int)Math.round(move(s.lp.x,target,pace));s.lp.x=Math.max(0,Math.min(s.width-s.lp.width,s.lp.x));if(Math.abs(s.lp.x+s.lp.width/2-bx-bp.width/2)<s.lp.width*.55&&by>floor-s.dp(40)){phase=2;catches++;}}
   if(phase==2){double target=homeCenter-s.lp.width/2;s.direction=target>=s.lp.x?1:-1;s.lp.x=(int)Math.round(move(s.lp.x,target,pace));bx=s.lp.x+s.lp.width*.60;by=floor-s.lp.height*.45;if(Math.abs(s.lp.x+s.lp.width/2-homeCenter)<s.dp(3)){phase=0;returns++;bx=homeCenter+s.dp(15);by=floor-bp.height;s.happyUntil=now+4000;s.setState(6,4000);}}
   s.lp.y=(int)floor-s.lp.height;s.clamp();s.update();walk(dt);updateBall();return true;
  }
  if(ballVisible&&!dragBall)updateBall();
  if(now<s.happyUntil||now<s.playUntil)return false;
  boolean sleeping=now-s.touched>=90000;
  if(goHome||(homeVisible&&sleeping)||mode==2){boolean arrived=movePet(homeCenter-s.lp.width/2,floor-s.lp.height,dt);if(arrived){goHome=false;s.row=sleeping?0:6;s.frame=sleeping?3:0;s.sleeping=sleeping;redraw();}return true;}
  if(mode==1){boolean arrived=movePet(companyX,companyY,dt);if(arrived){s.row=sleeping?0:6;s.frame=sleeping?3:0;s.sleeping=sleeping;redraw();}return true;}
  return false;
 }
 boolean movePet(double x,double y,int dt){if(Math.abs(s.lp.x-x)<s.dp(3)&&Math.abs(s.lp.y-y)<s.dp(3))return true;double d=s.dp(s.speed+20)*dt/1000.0;s.direction=x>=s.lp.x?1:-1;s.lp.x=(int)Math.round(move(s.lp.x,x,d));s.lp.y=(int)Math.round(move(s.lp.y,y,d));s.clamp();s.update();walk(dt);return Math.abs(s.lp.x-x)<s.dp(3)&&Math.abs(s.lp.y-y)<s.dp(3);}
 void walk(int dt){s.row=s.direction>0?1:2;s.age+=dt;while(s.age>=120){s.age-=120;s.frame=(s.frame+1)%8;}s.frame%=8;redraw();}
 void redraw(){if(s.row!=s.drawnRow||s.frame!=s.drawnFrame){s.pet.invalidate();s.drawnRow=s.row;s.drawnFrame=s.frame;}}
 void updateBall(){bp.x=(int)Math.round(bx);bp.y=(int)Math.round(by);s.wm.updateViewLayout(ball,bp);ball.invalidate();}
 void remind(){NotificationManager manager=(NotificationManager)s.getSystemService(Context.NOTIFICATION_SERVICE);NotificationChannel channel=new NotificationChannel("pip_reminders","Перерывы с Пипом",NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);manager.createNotificationChannel(channel);PendingIntent open=PendingIntent.getActivity(s,4,new Intent(s,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);manager.notify(18,new Notification.Builder(s,"pip_reminders").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("Перерыв с Пипом 🦊").setContentText("Может, пора размяться и отдохнуть от экрана?").setAutoCancel(true).setContentIntent(open).build());}
 void drawAccessory(Canvas c,int row,int frame,int width,int height){if(accessory==0)return;c.save();c.scale(width/192f,height/208f);float x=ax[row][frame],ey=ay[row][frame];Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);if(accessory==2){float y=Math.max(25,ey-24);p.setColor(Color.rgb(147,112,219));c.drawArc(new RectF(x-17,y-20,x+17,y+12),180,180,true,p);c.drawRect(x-21,y-5,x+21,y+3,p);p.setColor(Color.rgb(230,230,250));c.drawCircle(x,y-20,3,p);}else{x=row==1?x-16:row==2?x+16:row>=9?100+(x-100)*.35f:x;float y=Math.min(188,ey+32);p.setColor(accessory==1?Color.rgb(205,92,92):accessory==3?Color.rgb(220,20,60):accessory==4?Color.rgb(65,105,225):Color.rgb(46,139,87));p.setStrokeWidth(accessory==1?7:5);p.setStrokeCap(Paint.Cap.ROUND);c.drawLine(x-15,y,x+15,y,p);if(accessory==1){Path path=new Path();path.moveTo(x+5,y);path.lineTo(x+20,y+22);path.lineTo(x+9,y+21);path.lineTo(x-1,y+4);path.close();c.drawPath(path,p);}else{p.setColor(Color.rgb(255,215,0));c.drawOval(new RectF(x-3,y+3,x+3,y+10),p);}}c.restore();}
 void close(){try{s.wm.removeView(home);}catch(Exception e){}try{s.wm.removeView(ball);}catch(Exception e){}((NotificationManager)s.getSystemService(Context.NOTIFICATION_SERVICE)).cancel(18);}
 class Decor extends View {
  final boolean toy;Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);float downX,downY,lastX,lastY;int startX,startY;long lastTime;double speedX,speedY;
  Decor(boolean isBall){super(s);toy=isBall;setContentDescription(toy?"Мячик Пипа — брось его":"Домик Пипа — перетащи или нажми");}
  @Override protected void onDraw(Canvas c){super.onDraw(c);c.save();if(toy){c.scale(getWidth()/28f,getHeight()/28f);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(255,165,0));c.drawCircle(14,14,12,p);p.setColor(Color.rgb(0,128,128));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(5);c.drawArc(new RectF(4,5,24,22),25,220,false,p);p.setStyle(Paint.Style.FILL);p.setColor(Color.WHITE);c.drawOval(new RectF(7,6,12,10),p);}else{c.scale(getWidth()/88f,getHeight()/76f);p.setColor(Color.rgb(255,245,218));c.drawRect(12,28,76,72,p);p.setColor(Color.rgb(0,128,128));Path roof=new Path();roof.moveTo(5,31);roof.lineTo(44,5);roof.lineTo(83,31);roof.close();c.drawPath(roof,p);p.setColor(Color.rgb(117,78,56));c.drawArc(new RectF(33,41,55,69),180,180,true,p);c.drawRect(33,55,55,72,p);}c.restore();}
  @Override public boolean onTouchEvent(MotionEvent e){WindowManager.LayoutParams a=toy?bp:hp;switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:downX=lastX=e.getRawX();downY=lastY=e.getRawY();startX=a.x;startY=a.y;lastTime=SystemClock.uptimeMillis();speedX=0;speedY=-s.dp(100);if(toy){dragBall=true;phase=0;}s.touch();return true;
   case MotionEvent.ACTION_MOVE:long now=SystemClock.uptimeMillis();double seconds=Math.max(.01,(now-lastTime)/1000.0);speedX=(e.getRawX()-lastX)/seconds;speedY=(e.getRawY()-lastY)/seconds;lastX=e.getRawX();lastY=e.getRawY();lastTime=now;a.x=startX+Math.round(e.getRawX()-downX);a.y=startY+Math.round(e.getRawY()-downY);if(!toy)clampHome();s.wm.updateViewLayout(this,a);invalidate();return true;
   case MotionEvent.ACTION_UP:if(toy){dragBall=false;throwBall(a.x,a.y,Math.abs(speedX)<10?s.dp(120):speedX,Math.min(-s.dp(50),speedY));}else{saveHome();goHome=true;}performClick();return true;
   case MotionEvent.ACTION_CANCEL:dragBall=false;return true;}return true;}
  @Override public boolean performClick(){super.performClick();return true;}
 }
}
